from lib import *
S = SS('l71')
steps = [
    step("git credential 是 git 自己用的凭据协议的命令行入口:往 stdin 写 key=value 行、空行结束。git credential fill 的输入是 protocol=https、host=example.com;配置的 helper(credential.helper = lab,即 PATH 上的 git-credential-lab)被调用时的参数是 get,它从 stdin 收到同样的两行,返回 username=alice 和 password=…,fill 把它们补进输出。helper 什么也不返回、又禁止了终端提示(GIT_TERMINAL_PROMPT=0)时,fill 退出码 128:fatal: could not read Username for 'https://example.com': terminal prompts disabled。", t=tl(S(1)), mark=lidx(S(1), '[lab] get', 'terminal prompts disabled', 'username=alice'), done=lidx(S(1), 'protocol=https', 'host=example.com'), kv=KV([['协议', 'stdin/stdout 的 key=value 行,空行结束'], ['get', '向 helper 要凭据'], ['没有 helper 又不能提示', 'fatal: terminal prompts disabled']], ['协议'])),
    step("git credential approve 对应 helper 的 store(凭据可用,请保存):helper 收到 [lab] store 和 protocol、host、username、password;git credential reject 对应 erase(凭据被拒绝,请删除):收到 [lab] erase,同样带着用户名和密码。三个命令 get / store / erase 就是 helper 要实现的全部。", t=tl(S(2)), mark=lidx(S(2), '[lab] store', '[lab] erase'), done=lidx(S(2), 'username=alice', 'password=<已隐藏>'), kv=KV([['get', 'fill:要凭据'], ['store', 'approve:成功了,请保存'], ['erase', 'reject:失败了,请删掉']], ['store'])),
    step("url=https://bob@git.example.com/org/repo.git 会被拆成字段:protocol=https、host=git.example.com、username=bob——默认不传 path。设 credential.useHttpPath=true 之后,helper 多收到一行 path=org/repo.git,于是同一主机上的不同仓库可以用不同的凭据。", t=tl(S(3)), mark=lidx(S(3), 'path=org/repo.git', 'credential.useHttpPath=true'), done=lidx(S(3), '默认(不带 path)', 'host=git.example.com', 'username=bob'), kv=KV([['url', '被拆成 protocol / host / username …'], ['path', '默认不传'], ['useHttpPath=true', '按仓库区分凭据']], ['useHttpPath'])),
    step("真实流程:本机用 git http-backend 起一个要求 Basic 认证的 smart-http 服务。git ls-remote:第一个请求没带认证,服务器要求认证(401);git 于是调用 helper 的 get,stdin 里除了 protocol=http、host=127.0.0.1:9811,还有 capability[]=authtype、capability[]=state 和 wwwauth[]=Basic realm=\"git\"(服务器的认证质询);第二个请求带上认证,通过;git 调用 helper 的 store 保存凭据。helper 返回错误密码时:服务器拒绝第二个请求,git 报 fatal: Authentication failed,并调用 helper 的 erase,把这条凭据删掉。", t=tl(S(4)), mark=lidx(S(4), 'auth=无 要求认证', 'auth=有 拒绝', 'wwwauth[]=Basic realm="git"', '[lab] erase', 'Authentication failed'), done=lidx(S(4), '正确的凭据', 'auth=有 通过', '[lab] store'), kv=KV([['第一次请求', '不带认证 → 401'], ['helper get', '带 wwwauth 质询'], ['成功', 'store'], ['被拒绝', 'erase,然后失败']], ['helper get'])),
    step("多个 helper 按顺序询问:credential.helper 设了 lab 和 second 两个。fill 时先问 lab(没返回凭据),再问 second,second 给了 username=备用用户 和 password=…,fill 用它的。approve 时则通知所有 helper:lab 和 second 都收到了 store。也就是说取凭据是“第一个能给出的赢”,存凭据是“广播”。", t=tl(S(5)), mark=lidx(S(5), '[second] get', '[second] store'), done=lidx(S(5), '[lab] get', '[lab] store', '备用用户'), kv=KV([['get', '按顺序问,第一个给出的赢'], ['store / erase', '通知所有 helper']], ['get'])),
    step("自带的 credential-store helper:git credential approve 之后它在文件里写下 https://alice:<密码>@example.com——明文,权限 600(仅所有者可读写);之后 fill 不再需要提示,直接补出用户名和密码;reject 之后文件变成空的。内存里的 credential-cache、macOS 的 osxkeychain 等是另外的实现,协议相同。", t=tl(S(6)), mark=lidx(S(6), '明文', '权限 600', 'reject 之后文件内容'), done=lidx(S(6), '之后 fill 不再需要提示'), kv=KV([['credential-store', '明文文件,权限 600'], ['credential-cache', '内存 + 超时'], ['osxkeychain', 'macOS 钥匙串'], ['协议', '都是 get / store / erase']], ['credential-store'])),
]
A = mkarti('l71', 71, 'Git,credential helper,凭据,认证,真实验证,动画演示',
    '实测 git 的凭据协议:用 git credential fill / approve / reject 驱动 helper 的 get / store / erase,stdin 是 key=value 行;useHttpPath 决定是否传 path;用 git http-backend 起一个要求 Basic 认证的本机服务,看到 401 → helper get(带 wwwauth 质询)→ 带认证的请求 → store,密码错则 erase;多个 helper 取凭据按顺序第一个给出的赢、存凭据广播;credential-store 明文保存,权限 600。',
    'git 在 HTTPS 上怎么拿到密码?credential helper 到底收到什么、返回什么、什么时候被通知保存和删除?这篇用 git credential 命令直接驱动 helper,再在本机起一个要求认证的 smart-http 服务,把整个认证流程走一遍。',
    [('get / store / erase', 'credential helper 要实现的三个命令,对应 git credential 的 fill / approve / reject'), ('401 → get → store', '真实 HTTP 认证里,git 先试一次无认证请求,收到 401 后才向 helper 要凭据,成功后再 store'), ('明文 600', 'credential-store 把凭据以明文写进文件,只靠文件权限保护')],
    [('协议', '<p>git 与 helper 之间是极简的文本协议:stdin/stdout 上的 <code>key=value</code> 行,空行结束。helper 是 PATH 上的 <code>git-credential-&lt;名&gt;</code>。<code>git credential fill</code> 调用它的 <code>get</code>;没有 helper 能给出凭据又不允许提示终端时,fill 以 128 退出。</p>'),
     ('store 与 erase', '<p><code>git credential approve</code> 对应 helper 的 <code>store</code>(凭据可用,保存),<code>reject</code> 对应 <code>erase</code>(凭据被拒绝,删除)。get / store / erase 就是 helper 要实现的全部。</p>'),
     ('字段', '<p>url 被拆成 <code>protocol</code>、<code>host</code>、<code>username</code> 等字段;默认不传 <code>path</code>,<code>credential.useHttpPath=true</code> 才传,用来区分同一主机上的不同仓库。新版 git 还会传 <code>capability[]</code> 和服务器的 <code>wwwauth[]</code> 质询。</p>'),
     ('真实流程', '<p>git 第一个请求不带认证,服务器回 401 后 git 才调用 helper 的 <code>get</code>,拿到凭据重发请求;成功就 <code>store</code>,被拒绝就 <code>erase</code> 并报 <code>Authentication failed</code>。</p>'),
     ('多个 helper', '<p>取凭据按配置顺序询问,第一个给出完整用户名和密码的赢;<code>store</code> 和 <code>erase</code> 通知所有 helper。</p>'),
     ('自带的 helper', '<p><code>credential-store</code> 以明文把 <code>https://用户:密码@主机</code> 写进文件(权限 600);<code>credential-cache</code> 放内存里并设超时;macOS 的 <code>osxkeychain</code> 用钥匙串。协议相同,安全性不同。</p>')],
    steps,
    [ENV_I_GIT + '。全部实验都在隔离的 HOME 和实验专用 helper 下进行,没有碰真实的钥匙串或 ~/.git-credentials;HTTP 服务是我写的几十行 Python,把请求交给 git http-backend 并在前面加 Basic 认证;helper 是记录型 shell 脚本;日志里的密码做了隐藏',
     '没有验证:credential-cache 的超时与守护进程;osxkeychain、Git Credential Manager 等真实 helper;OAuth/Bearer 方式(authtype 能力的实际用法);ssh 认证(与此协议无关);http.proactiveAuth;helper 的 quit 字段与多行属性的处理细节'],
    'credential helper')
